const listStaleFilesInFolders = `-- name: ListStaleFilesInFolders :many
SELECT f.repo_key, f.path, f.name
FROM items d
JOIN repositories r ON r.key = d.repo_key AND r.format = ANY($1::text[])
JOIN items f ON f.repo_key = d.repo_key
    AND f.path = CASE WHEN d.path = '.' THEN d.name ELSE d.path || '/' || d.name END
WHERE d.type = 'folder' AND d.name = $2 AND f.type = 'file' AND f.modified < $3::timestamptz
ORDER BY f.repo_key, f.path, f.name
LIMIT $4
`

